import Foundation

/// Our own photos of sealed products (backgrounds removed), served by the website from
/// `public/products/<dir>/<file>.webp`. The list is `SealedArtList.swift`, generated by
/// `scripts/sealed-art.py` from the website's `src/lib/sealed-art-manifest.json`, and the
/// matching is the same as `src/lib/sealed-art.ts`:
/// - the set: the one whose name (or another name it goes by) sits latest in the product's set
///   name ("Mega Evolution—Delta Reign" is Delta Reign), else in the product's own name;
/// - the product: its name without the set's names matched against the listed products (also
///   without their set's names and, as a second try, their bracketed notes): exactly, else the
///   longest listed name inside it ("Elite Trainer Box Case" is the case, not the box).
enum SealedArt {
    struct Entry {
        var set: String
        var aliases: [String]
        var dir: String
        var products: [String: String]
    }

    private struct Prepared {
        var entry: Entry
        /// The set's names as words, longest first.
        var names: [String]
        /// Each listed product as words (without the set's names), twice: as listed and without bracketed notes.
        var keys: [(label: String, words: String)]
    }

    /// Lowercase words only: "Build & Battle Box" → "build and battle box".
    static func words(_ s: String) -> String {
        s.lowercased()
            .replacingOccurrences(of: "é", with: "e")
            .replacingOccurrences(of: "&", with: " and ")
            .replacingOccurrences(of: #"[^a-z0-9]+"#, with: " ", options: .regularExpression)
            .trimmingCharacters(in: .whitespaces)
    }

    /// Where `needle` starts in `hay` as whole words, or nil.
    private static func at(_ hay: String, _ needle: String) -> Int? {
        guard !needle.isEmpty, let r = " \(hay) ".range(of: " \(needle) ") else { return nil }
        return " \(hay) ".distance(from: " \(hay) ".startIndex, to: r.lowerBound)
    }

    private static func without(_ s: String, _ names: [String]) -> String {
        var out = " \(s) "
        for n in names where !n.isEmpty { out = out.replacingOccurrences(of: " \(n) ", with: " ") }
        return out.split(separator: " ").joined(separator: " ")
    }

    private static let prepared: [Prepared] = entries.map { e in
        let names = ([e.set] + e.aliases).map(words).sorted { $0.count > $1.count }
        func strip(_ k: String) -> String { without(without(words(k), names), ["mega evolution", "pokemon"]) }
        let keys = e.products.keys.flatMap { k in
            [(label: k, words: strip(k)),
             (label: k, words: strip(k.replacingOccurrences(of: #"\([^)]*\)|\[[^\]]*\]"#, with: " ", options: .regularExpression)))]
        }.filter { !$0.words.isEmpty }
        return Prepared(entry: e, names: names, keys: keys)
    }

    /// The set a product belongs to: the set name found latest in `hay`.
    private static func pickSet(_ hay: String) -> Prepared? {
        var best: Prepared?
        var bestAt = -1
        var bestLen = 0
        for p in prepared {
            for n in p.names {
                guard let i = at(hay, n) else { continue }
                // Latest first; starting at the same place, the longer name.
                if i > bestAt || (i == bestAt && n.count > bestLen) {
                    best = p
                    bestAt = i
                    bestLen = n.count
                }
            }
        }
        return best
    }

    /// Worked out once per product name and set.
    nonisolated(unsafe) private static var cache: [String: String?] = [:]
    private static let lock = NSLock()

    /// The photo's path on the website ("/products/pokemon/delta-reign/delta-reign-booster-box.webp"), or nil.
    static func path(name: String, setName: String?, single: Bool) -> String? {
        guard !single else { return nil }
        let key = "\(name)|\(setName ?? "")"
        lock.lock(); if let hit = cache[key] { lock.unlock(); return hit }; lock.unlock()
        let found = match(name: name, setName: setName)
        lock.lock(); cache[key] = found; lock.unlock()
        return found
    }

    private static func match(name rawName: String, setName rawSet: String?) -> String? {
        let name = words(rawName)
        guard let set = pickSet(words(rawSet ?? "")) ?? pickSet(name) else { return nil }
        // The product part: its name without the set's names, the series or a code ("ME03", "SV08").
        let rest = without(name, set.names + ["mega evolution", "pokemon"])
            .replacingOccurrences(of: #"\b(me|sv|swsh)\d+[a-z]?\b"#, with: " ", options: .regularExpression)
            .split(separator: " ").joined(separator: " ")
        let pick = set.keys.first { $0.words == rest }
            ?? set.keys.filter { at(rest, $0.words) != nil }.max { $0.words.count < $1.words.count }
        guard let pick, let file = set.entry.products[pick.label] else { return nil }
        return "/products/\(set.entry.dir)/\(file).webp"
    }

    static func url(_ p: Product) -> URL? {
        path(name: p.name, setName: p.setName, single: !p.isSealed).map { AppConfig.apiBaseURL.appendingPathComponent(String($0.dropFirst())) }
    }
}
